898	export const buildRuleStack = (
899	  linearRules: InternalRuleDef[],
900	): UnresolvedRule[][] => {
901	  let paths: UnresolvedRule[] = [];
902	  const stack: UnresolvedRule[][] = [];
903	  let idx = 0;
904	
905	  while (idx < linearRules.length) {
906	    const ruleDef = linearRules[idx];
907	    if (isRuleDefChar(ruleDef) || isRuleDefCharNot(ruleDef)) {
908	      // this could be a single char, or a range, or a sequence of alts; we don't know until we step through it.
909	      const charRule = makeCharRule(ruleDef);
910	      idx += 1;
911	      let rule: InternalRuleDef | undefined =
912	        idx < linearRules.length ? linearRules[idx] : undefined;
913	      while (
914	        idx < linearRules.length &&
915	        (isRuleDefCharRngUpper(rule) || isRuleDefCharAlt(rule))
916	      ) {
917	        if (isRuleDefCharRngUpper(rule)) {
918	          // previous rule value should be a number
919	          const prevValue = charRule.value.pop();
920	          if (isRange(prevValue)) {
921	            throw new Error(
922	              `Unexpected range, expected a number but got an array: ${JSON.stringify(prevValue)}`,
923	            );
924	          }
925	          if (prevValue === undefined) {
926	            throw new Error('Unexpected undefined value');
927	          }
928	
929	          charRule.value.push([prevValue as number, rule.value]);
930	        }
931	        if (isRuleDefCharAlt(rule)) {
932	          charRule.value.push(rule.value);
933	        }
934	        idx += 1;
935	        rule = idx < linearRules.length ? linearRules[idx] : undefined;
936	      }
937	      paths.push(charRule);
938	    } else {
939	      if (isRuleDefAlt(ruleDef)) {
940	        if (paths.length === 0) {
941	          throw new Error('Encountered alt without anything before it');
942	        }
943	        paths.push(new RuleEnd());
944	        stack.push(paths);
945	        paths = [];
946	      } else if (isRuleDefEnd(ruleDef)) {
947	        paths.push(new RuleEnd());
948	      } else if (isRuleDefRef(ruleDef)) {
949	        paths.push(new RuleRef(ruleDef.value));
950	      } else if (isRuleDefCharAlt(ruleDef)) {
951	        throw new Error(
952	          `Encountered char alt, should be handled by above block: ${ruleDef}`,
953	        );
954	      } else {
955	        throw new Error(`Unsupported rule type: ${ruleDef}`);
956	      }
957	      idx += 1;
958	    }
959	  }
960	
961	  if (!isRuleEnd(paths[paths.length - 1])) {
962	    paths.push(new RuleEnd());
963	  }
964	
965	  stack.push(paths);
