996	export const parseChar = (src: string, pos: number): [number, number] => {
997	  if (pos >= src.length) {
998	    throw new GrammarParseError(
999	      src,
1000	      pos,
1001	      'Unexpected end of grammar input, failed to complete parse',
1002	    );
1003	  }
1004	
1005	  if (src[pos] === '\\') {
1006	    const next = src[pos + 1];
1007	    if (next === 'x') {
1008	      return [parseInt(src.slice(pos + 2, pos + 4), 16), 4];
1009	    }
1010	    if (next === 'u') {
1011	      return [parseInt(src.slice(pos + 2, pos + 6), 16), 6];
1012	    }
1013	    if (next === 'U') {
1014	      return [parseInt(src.slice(pos + 2, pos + 10), 16), 10];
1015	    }
1016	    if (next in ESCAPE_CODES) {
1017	      return [ESCAPE_CODES[next], 2];
1018	    }
1019	    if (['"', '[', ']', '\\'].includes(next)) {
1020	      return [next.codePointAt(0) as number, 2];
1021	    }
1022	    throw new GrammarParseError(src, pos, `Unknown escape at ${src[pos]}`);
1023	  }
1024	
1025	  return [src.codePointAt(pos) as number, 1];
1026	};
