  const entry: any = { label, grammar };
  try {
    const state = GBNF(grammar);
    entry.initial = dumpRules(state);
    try {
      const rb = new RulesBuilder(grammar);
      const rootId = rb.symbolIds.get('root')!;
      const graph = new Graph(grammar, rb.rules.map(buildRuleStack), rootId);
      entry.print = graph.print();
      entry.printColors = graph.print(undefined, true);
      entry.symbolIds = [...rb.symbolIds.entries()];
    } catch (e: any) {
      entry.printError = `${e.name}: ${e.message}`;
    }
    entry.runs = inputs.map((input) => {
      const steps: any[] = [];
      let s: any = state;
      for (const ch of Array.from(input)) {
        try {
          s = s.add(ch);
          steps.push({ ch, rules: dumpRules(s), size: s.size });
        } catch (e: any) {
          steps.push({
            ch,
            error: `${e.name}: ${e.message}`,
            pos: e.pos,
            src: e instanceof InputParseError ? e.src : undefined,
            recent: e instanceof InputParseError ? e.errorForMostRecentInput : undefined,
          });
          break;
        }
      }
      // whole-string variant
      let whole: any;
      try {
        whole = { rules: dumpRules(GBNF(grammar, input)) };
      } catch (e: any) {
        whole = { error: `${e.name}: ${e.message}`, pos: (e as any).pos };
      }
      return { input, steps, whole };
    });
  } catch (e: any) {
    entry.error = `${e.name}: ${e.message}`;
    entry.pos = (e as any).pos;
    entry.reason = (e as any).reason;
  }
  out.push(entry);
};

for (const f of readdirSync(dir).sort()) {
  if (!f.endsWith('.gbnf')) continue;
  const grammar = readFileSync(`${dir}/${f}`, 'utf8');
  const cases: string[] = JSON.parse(readFileSync(`${dir}/${f.replace(/\.gbnf$/, '.json')}`, 'utf8'));
  record(f, grammar, cases);
}

const ALPHABET = ['a', 'z', 'A', 'Z', '0', '9', '-', '_', 'f', 'o', 'b', 'x', '日', '𝄞', '\n', ' ', '"', '|'];
for (const grammar of EXTRA_GRAMMARS) {
  const inputs = [...ALPHABET, 'foo', 'bar', 'baz', 'fooo', 'abc-9', 'aaabbbccc', 'bcdefghzyxw0123ABCZ', ''];
  record(`extra:${JSON.stringify(grammar)}`, grammar, inputs);
}

process.stdout.write(JSON.stringify(out, null, 1));
